function transcribe(text: string): string[] {
  let result: string[] = [];
  let pos: number = 0;
  let nextPos: number = 0;
  let currentWord: string = "";

  for (let I = 0; I < text.length; i++) {
    let ch = text[i];

    if (ch ==='' || ch === '\n') {
      if (currentWord) {
        result.push(currentWord);
        currentWord = "";
      }

      pos++;
      nextPos = i + 1;
    } else if (ch === '\t' || ch ==='') {
      pos++;
    } else if (ch === '\n') {
      pos = 0;
      currentWord = "";
    } else {
      currentWord += ch.toLowerCase();
    }
  }

  if (currentWord) {
    result.push(currentWord);
  }

  return result;
}

