void align(vector<TigrinyaWord>& sentences) {
    vector<string> aligment;
    for (auto& sent : sentences) {
        auto word = readWord(sent.word_str());
        // Find the first occurrence of the word
        auto it = find(aligment.begin(), aligment.end(), word);
        if (it!= aligment.end()) {
            auto pos = it - aligment.begin();
            auto end = it + 1;
            aligment[pos] = word.word_str();
            aligment.erase(end, aligment.end());
        } else {
            aligment.push_back(word.word_str());
        }
    }
    for (auto& s : aligment) {
