    cout << "Enter a list of English words separated by spaces: ";
    getline(cin, word);
    // Remove leading and trailing spaces
    len = word.length();
    for (int i = 0; i < len; i++) {
        if (word[i] =='') {
            word[i] = '\0';
        }
    }
    // Convert list to lowercase
    string::iterator it;
    for (it = word.begin(); it!= word.end(); it++) {
        *it = tolower(*it);
    }
    // Convert list to string
    string tigrinya_word;
    for (it = word.begin(); it!= word.end(); it++) {
        tigrinya_word.append(*it);
    }
    // Print translation
    cout << "English word: " << tigrinya_word << endl;
    return 0;
}
