import re

class Translator:
    def __init__(self):
        self.word_to_english = {}
        self.english_to_tigrinya = {}

    def translate(self, word):
        if word in self.word_to_english:
            return self.word_to_english[word]
        if word in self.english_to_tigrinya:
            return self.english_to_tigrinya[word]
        return word

    def word_to_tigrinya(self, word):
        if word in self.english_to_tigrinya:
            return self.english_to_tigrinya[word]
        return re.sub(r'አንተ', 'ተረት', word)

    def tigrinya_to_english(self, tigrinya_word):
        if tigrinya_word in self.tigrinya_to_english:
            return self.tigrinya_to_english[tigrinya_word]
        return tigrinya_word

if __name__ == '__main__':
    translator = Translator()
    for word, translation in zip(["ጎራሕ", "የትንሊያቸው"], ["ግርግብ"]):
        print(translator.translate(word), translator.tigrinya_to_english(translator.translate(word)))

