You can use the `map()` function in the `reduce()` function to perform the mappings.

```js
const map = (str, map) => {
  for (let I = 0; I < str.length; i++) {
    const char = str[i];
    for (let j = 0; j < map.length; j++) {
      if (map[j] === char) {
        str[i] = map[i];
        break;
      }
    }
  }
  return str;
};

const words = ["ጽላል", "ፅምሜ", "ንተርጉ"];
const translations = words.map(map(str => str.split("").join(""), Tigrinya));
